/*
 * prog36_pascal_triangle – re‑implementation
 *
 * Behaviour (identical to the original obfuscated binary):
 *
 *   No command‑line argument          -> prints "NO_INPUT"
 *   Argument not a valid integer      -> prints "BAD_INPUT"
 *   Argument is a negative number     -> prints "BAD_INPUT"
 *   Argument is 0                     -> prints "EMPTY"
 *   Argument > 60                     -> prints "OUT_OF_RANGE"
 *   1 ≤ n ≤ 60                        -> prints the first n rows of Pascal's
 *                                        triangle, each number printed with
 *                                        "%lld", a single space between numbers,
 *                                        and a newline after each row.
 *
 * The implementation follows the same limits and output format as the
 * original program, using a single array of 61 `long long` elements and
 * updating the current row in‑place from right to left.
 */

#include <stdio.h>
#include <stdlib.h>
#include <errno.h>

int main(int argc, char *argv[])
{
    /* ---------- argument handling ---------- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    errno = 0;
    long long n = strtoll(argv[1], &endptr, 10);

    /* not a number, extra characters after the number, or overflow */
    if (endptr == argv[1] || *endptr != '\0' || errno == ERANGE) {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0) {                 /* negative numbers are invalid */
        puts("BAD_INPUT");
        return 0;
    }

    if (n == 0) {
        puts("EMPTY");
        return 0;
    }

    if (n > 60) {                /* the internal array has size 61 */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ---------- Pascal triangle generation ---------- */
    long long row[61] = {0};
    row[0] = 1;                  /* first row */

    for (long long i = 0; i < n; ++i) {
        /* print current row */
        for (long long j = 0; j <= i; ++j) {
            printf("%lld", row[j]);
            if (j < i)
                putchar(' ');
        }
        putchar('\n');

        /* compute next row in‑place (right‑to‑left) */
        row[i + 1] = 1;                     /* new rightmost 1 */
        for (long long j = i; j > 0; --j)   /* update interior values */
            row[j] = row[j] + row[j - 1];
        /* row[0] stays 1 */
    }

    return 0;
}
